    **2. Create `packages/sdk-core/src/pinning/pinata-provider.ts`:**

    Pinata API reference (v3):
    - **Upload file:** `POST https://uploads.pinata.cloud/v3/files` with multipart form data. Header: `Authorization: Bearer <JWT>`. Response: `{ data: { id: string, cid: string, size: number } }`
    - **Pin by CID (existing content):** `POST https://api.pinata.cloud/pinning/pinByHash` with `{ hashToPin: cid }`. Header: `Authorization: Bearer <JWT>`. Response: `{ id: string, ipfsHash: string, status: string }`
    - **List files:** `GET https://api.pinata.cloud/v3/files?cid=<cid>`. Response: `{ data: { files: [{ id, cid, size }] } }`
    - **Unpin file:** `DELETE https://api.pinata.cloud/v3/files/<id>`. Response: 200 OK
    - **Get file:** `GET https://<gateway>/ipfs/<cid>` -- Pinata provides a dedicated gateway per account

    Note: Pinata uses TWO base URLs:
    - `https://uploads.pinata.cloud` for file uploads
    - `https://api.pinata.cloud` for management operations (list, delete, pinByHash)

    The `endpoint` config should be `https://api.pinata.cloud` (the management endpoint). Uploads always go to the fixed `https://uploads.pinata.cloud`.

    Implementation:

    ```typescript
    import type { PinningProvider, PinResult, PinStatus } from './types';

    const UPLOAD_URL = 'https://uploads.pinata.cloud';
    const REQUEST_TIMEOUT_MS = 60_000;

    export class PinataProvider implements PinningProvider {
      private readonly endpoint: string; // https://api.pinata.cloud
      private readonly authToken: string; // Pinata JWT
      private readonly gatewayUrl?: string; // Optional dedicated gateway

      constructor(endpoint: string, authToken: string, gatewayUrl?: string) {
        this.endpoint = endpoint.replace(/\/+$/, '');
        this.authToken = authToken;
        this.gatewayUrl = gatewayUrl?.replace(/\/+$/, '');
      }

      async pin(data: Uint8Array, name?: string): Promise<PinResult> {
        const blob = new Blob([data]);
        const formData = new FormData();
        formData.append('file', blob, name ?? `cipherbox-${Date.now()}`);

        const response = await fetch(`${UPLOAD_URL}/v3/files`, {
          method: 'POST',
          headers: { Authorization: `Bearer ${this.authToken}` },
          body: formData,
          signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
        });

        if (!response.ok) {
          const errorText = await response.text();
          throw new Error(`Pinata upload failed: ${response.status} - ${errorText}`);
        }

        const result = (await response.json()) as {
          data: { id: string; cid: string; size: number };
        };
        return { cid: result.data.cid, size: result.data.size };
      }

      async pinByCid(cid: string): Promise<{ cid: string; status: string }> {
        const response = await fetch(`${this.endpoint}/pinning/pinByHash`, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${this.authToken}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ hashToPin: cid }),
          signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
        });

        if (!response.ok) {
          const errorText = await response.text();
          throw new Error(`Pinata pinByHash failed: ${response.status} - ${errorText}`);
        }

        const result = (await response.json()) as { ipfsHash: string; status: string };
        return { cid: result.ipfsHash, status: result.status };
      }

      async unpin(cid: string): Promise<void> {
        // Find the file ID by CID first
        const listResponse = await fetch(
          `${this.endpoint}/v3/files?cid=${encodeURIComponent(cid)}`,
          {
            method: 'GET',
            headers: { Authorization: `Bearer ${this.authToken}` },
            signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
          }
        );

        if (!listResponse.ok) {
          throw new Error(`Pinata list failed: ${listResponse.status}`);
        }

        const listResult = (await listResponse.json()) as {
          data: { files: Array<{ id: string }> };
        };

        for (const file of listResult.data.files) {
          const deleteResponse = await fetch(`${this.endpoint}/v3/files/${file.id}`, {
            method: 'DELETE',
            headers: { Authorization: `Bearer ${this.authToken}` },
            signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
          });
          if (!deleteResponse.ok) {
            throw new Error(`Pinata delete failed: ${deleteResponse.status}`);
          }
        }
      }

      async status(cid: string): Promise<PinStatus> {
        const response = await fetch(
          `${this.endpoint}/v3/files?cid=${encodeURIComponent(cid)}`,
          {
            method: 'GET',
            headers: { Authorization: `Bearer ${this.authToken}` },
            signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
          }
        );

        if (!response.ok) return { cid, status: 'failed' };

        const result = (await response.json()) as {
          data: { files: Array<{ id: string; cid: string }> };
        };

        return {
          cid,
          status: result.data.files.length > 0 ? 'pinned' : 'failed',
        };
      }

      async get(cid: string): Promise<Uint8Array> {
        const gateway = this.gatewayUrl ?? 'https://gateway.pinata.cloud';
